import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"損","description":"焦氏易林注 - 損","frontmatter":{"title":"損","description":"焦氏易林注 - 損"},"headers":[],"relativePath":"zh/classics/jiaoyilin/041.md","filePath":"zh/classics/jiaoyilin/041.md"}'),l={name:"zh/classics/jiaoyilin/041.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="損" tabindex="-1">損 <a class="header-anchor" href="#損" aria-label="Permalink to “損”">​</a></h1><h3 id="損-1" tabindex="-1">損 <a class="header-anchor" href="#損-1" aria-label="Permalink to “損”">​</a></h3><h3 id="損之乾" tabindex="-1">損之乾 <a class="header-anchor" href="#損之乾" aria-label="Permalink to “損之乾”">​</a></h3><h3 id="林辞" tabindex="-1">林辞 <a class="header-anchor" href="#林辞" aria-label="Permalink to “林辞”">​</a></h3><p>鯉鮪鯽鰕，積福多魚。資所無有，富我邦家。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>此用《損》象。坤為魚、為積、為邦家，本卦乾為福、為富。○鮪鯽，宋元本作鮒鮪，積作，均依汲古。邦，汲古作窮，依宋元本。</p><h3 id="損之坤" tabindex="-1">損之坤 <a class="header-anchor" href="#損之坤" aria-label="Permalink to “損之坤”">​</a></h3><h3 id="林辞-1" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-1" aria-label="Permalink to “林辞”">​</a></h3><p>景星照堂，麟游鳳翔。仁施大行，傾聲作興。徵者無明，失其寵光。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>此仍用遇卦象。詳《豫》之《節》。</p><h3 id="損之屯" tabindex="-1">損之屯 <a class="header-anchor" href="#損之屯" aria-label="Permalink to “損之屯”">​</a></h3><h3 id="林辞-2" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-2" aria-label="Permalink to “林辞”">​</a></h3><p>羊腸九縈，相推稍前。止須王孫，乃能上天。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>詳《臨》之《巽》。○上，汲古作至，依宋元本。</p><h3 id="損之蒙" tabindex="-1">損之蒙 <a class="header-anchor" href="#損之蒙" aria-label="Permalink to “損之蒙”">​</a></h3><h3 id="林辞-3" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-3" aria-label="Permalink to “林辞”">​</a></h3><p>四手共身，莫適所閑。更相訪接，動失事便。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>坤為身，震卦數四，艮手故曰四手共身。坤閉，故曰閑。震言，艮手，正反艮震，故曰更相訪接、失事便也。○閑，汲古作國，依宋元本。</p><h3 id="損之需" tabindex="-1">損之需 <a class="header-anchor" href="#損之需" aria-label="Permalink to “損之需”">​</a></h3><h3 id="林辞-4" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-4" aria-label="Permalink to “林辞”">​</a></h3><p>水流趨下，遠至東海。求我所有，賈魴與鯉。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>詳《益》之《無妄》。</p><h3 id="損之訟" tabindex="-1">損之訟 <a class="header-anchor" href="#損之訟" aria-label="Permalink to “損之訟”">​</a></h3><h3 id="林辞-5" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-5" aria-label="Permalink to “林辞”">​</a></h3><p>春慄秋棗，山鮮希有。鬥千石萬，貴不可販。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>詳《否》之《漸》。○山，元本作少，依汲古。</p><h3 id="損之師" tabindex="-1">損之師 <a class="header-anchor" href="#損之師" aria-label="Permalink to “損之師”">​</a></h3><h3 id="林辞-6" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-6" aria-label="Permalink to “林辞”">​</a></h3><p>旦往暮還，相佑與聚，無有凶患。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>震為旦、為行、為歸，坎為暮，坤為聚、為凶患。</p><h3 id="損之比" tabindex="-1">損之比 <a class="header-anchor" href="#損之比" aria-label="Permalink to “損之比”">​</a></h3><h3 id="林辞-7" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-7" aria-label="Permalink to “林辞”">​</a></h3><p>大蛇當路，使季畏懼。湯火之災，切近我膚。賴其天辛，歸於室廬。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《井》。○室，宋元本作生，依汲古。近，各本作直，依《屯》之《井》校。</p><h3 id="損之小畜" tabindex="-1">損之小畜 <a class="header-anchor" href="#損之小畜" aria-label="Permalink to “損之小畜”">​</a></h3><h3 id="林辞-8" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-8" aria-label="Permalink to “林辞”">​</a></h3><p>徙足去域，飛入陳國。有所畏避，深藏邃匿。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>通《豫》。震為足，艮為域、為飛、為國，震為陳，故曰飛入陳國。坎為畏避、為藏匿，全用伏象。○徙，宋元本作徒，依汲古。飛，汲古作亂，依宋元。</p><h3 id="損之履" tabindex="-1">損之履 <a class="header-anchor" href="#損之履" aria-label="Permalink to “損之履”">​</a></h3><h3 id="林辞-9" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-9" aria-label="Permalink to “林辞”">​</a></h3><p>海為水宗，聰聖且明。百流歸德，無有叛逆，常饒優足。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>詳《蒙》之《乾》。第二句宋本、汲古作聰明且聖，依元本。德，汲古作得，依宋元本。</p><h3 id="損之泰" tabindex="-1">損之泰 <a class="header-anchor" href="#損之泰" aria-label="Permalink to “損之泰”">​</a></h3><h3 id="林辞-10" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-10" aria-label="Permalink to “林辞”">​</a></h3><p>夏麥，霜擊其芒。病君敗國，使年大傷。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>詳《泰》之《賁》。○，汲古作曲，病作疚。</p><h3 id="損之否" tabindex="-1">損之否 <a class="header-anchor" href="#損之否" aria-label="Permalink to “損之否”">​</a></h3><h3 id="林辞-11" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-11" aria-label="Permalink to “林辞”">​</a></h3><p>秋隼冬翔，數被嚴霜。雄犬夜鳴，家擾不寧。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>詳《賁》之《隨》。○擾，各本皆作憂，依《賁》林校。嚴，汲古作履，依宋元本。</p><h3 id="損之同人" tabindex="-1">損之同人 <a class="header-anchor" href="#損之同人" aria-label="Permalink to “損之同人”">​</a></h3><h3 id="林辞-12" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-12" aria-label="Permalink to “林辞”">​</a></h3><p>樂仁上德，東鄰慕義，來興吾國。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>乾為仁德，離為東鄰，伏坤為義、為國。</p><h3 id="損之大有" tabindex="-1">損之大有 <a class="header-anchor" href="#損之大有" aria-label="Permalink to “損之大有”">​</a></h3><h3 id="林辞-13" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-13" aria-label="Permalink to “林辞”">​</a></h3><p>逐憂除殃，污泥生粱。下田為汪。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>坎為憂、為殃，坎伏故曰除。坎為污泥，坤為粱、為水、為下，故曰為汪。汪，瀦水也。○汪，汲古作江，依宋元本。逐，汲古作還，非，依宋元本。</p><h3 id="損之謙" tabindex="-1">損之謙 <a class="header-anchor" href="#損之謙" aria-label="Permalink to “損之謙”">​</a></h3><h3 id="林辞-14" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-14" aria-label="Permalink to “林辞”">​</a></h3><p>暗昧冥語，轉相迷誤。鬼魅所居，誰知卧處。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>坎隱故暗昧，正反震故語迷誤。坤為迷、為鬼，艮為卧，坤迷坎隱，故不知。</p><h3 id="損之豫" tabindex="-1">損之豫 <a class="header-anchor" href="#損之豫" aria-label="Permalink to “損之豫”">​</a></h3><h3 id="林辞-15" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-15" aria-label="Permalink to “林辞”">​</a></h3><p>南厯玉田，東入玉關。登上福堂，飲萬歲漿。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>震為南、為玉，艮為田、為關、為堂，坤為萬歲、為漿。玉關，玉門關，《漢書班超傳》：&quot;但願生入玉門關&quot;。玉田，疑指和闐，和闐在南疆，出玉。</p><h3 id="損之隨" tabindex="-1">損之隨 <a class="header-anchor" href="#損之隨" aria-label="Permalink to “損之隨”">​</a></h3><h3 id="林辞-16" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-16" aria-label="Permalink to “林辞”">​</a></h3><p>比目四翼，來安我國。福善上堂，與我同床。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>互大離，若兩目相比，故曰比目。比目，魚名。巽為魚，震為翼，卦數四，故曰四翼。艮為國、為堂、為床。</p><h3 id="損之蠱" tabindex="-1">損之蠱 <a class="header-anchor" href="#損之蠱" aria-label="Permalink to “損之蠱”">​</a></h3><h3 id="林辞-17" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-17" aria-label="Permalink to “林辞”">​</a></h3><p>乘牛逐驥，日暮不至。路宿多畏，亡其騂騅。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>艮牛震馬，故曰乘牛逐驥。艮為日，兌向晦，故曰日暮、曰路宿。艮為路，納丙，色赤，故曰騂。震青，故曰騅。兌折，故亡。牛行遲，驥行速，乘牛逐驥，斷不能及，故亡其騂騅也。</p><h3 id="損之臨" tabindex="-1">損之臨 <a class="header-anchor" href="#損之臨" aria-label="Permalink to “損之臨”">​</a></h3><h3 id="林辞-18" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-18" aria-label="Permalink to “林辞”">​</a></h3><p>元吉無咎，安寧不殆。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>震為元。n</p><h3 id="損之觀" tabindex="-1">損之觀 <a class="header-anchor" href="#損之觀" aria-label="Permalink to “損之觀”">​</a></h3><h3 id="林辞-19" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-19" aria-label="Permalink to “林辞”">​</a></h3><p>奮翅鼓翼，翱翔外國。逍遙徙倚，來歸溫室。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>伏震為翼、為飛，坤為國，艮陽在上故曰外國。艮為室，艮火故曰溫室。</p><h3 id="損之噬嗑" tabindex="-1">損之噬嗑 <a class="header-anchor" href="#損之噬嗑" aria-label="Permalink to “損之噬嗑”">​</a></h3><h3 id="林辞-20" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-20" aria-label="Permalink to “林辞”">​</a></h3><p>河伯娶婦，東山氏女。新婚三日，浮雲灑雨。露我菅茅，萬邦蒙佑。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>坎為河，震為伯，離為坎婦，震為娶、為東，艮為山，故曰東山氏女。坎為婚，離日，震數三，故曰三日。坎為雲雨、為露，震為草莽，在坎下，故曰露我菅茅。艮為邦，震為萬。《史記》西門豹為鄴令，三老五更為河伯娶婦。然下雲東山氏女，似別有故實。○露，宋元本作雨，蒙作之，依汲古。茅，汲古作第，非。</p><h3 id="損之賁" tabindex="-1">損之賁 <a class="header-anchor" href="#損之賁" aria-label="Permalink to “損之賁”">​</a></h3><h3 id="林辞-21" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-21" aria-label="Permalink to “林辞”">​</a></h3><p>嬰兒求乳，慈母歸子，黃麑悅喜。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>依《履》之《同人》刪末句得見甘飽四字。</p><h3 id="損之剝" tabindex="-1">損之剝 <a class="header-anchor" href="#損之剝" aria-label="Permalink to “損之剝”">​</a></h3><h3 id="林辞-22" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-22" aria-label="Permalink to “林辞”">​</a></h3><p>貧鬼守門，日破我盆。毀罌傷瓶，空虛無子。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>坤為鬼、為貧、為門，艮為守、為日，伏兌為破。震為罌瓶、為子，震覆故曰破、曰傷、曰無子。坤為虛。○瓶，元刊作缸，依宋本、汲古。</p><h3 id="損之復" tabindex="-1">損之復 <a class="header-anchor" href="#損之復" aria-label="Permalink to “損之復”">​</a></h3><h3 id="林辞-23" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-23" aria-label="Permalink to “林辞”">​</a></h3><p>多載重負，棄捐於野。王母誰子，但自勞苦。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>坤厚故能多載重負。坤為野，坤喪故曰棄捐於野。坤為母，震為王、為子，坤死故曰王母誰子，言無子也。坤為勞。○第三句宋元本作予無稚子，汲古作手無誰子，依局本。</p><h3 id="損之無妄" tabindex="-1">損之無妄 <a class="header-anchor" href="#損之無妄" aria-label="Permalink to “損之無妄”">​</a></h3><h3 id="林辞-24" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-24" aria-label="Permalink to “林辞”">​</a></h3><p>雄狐綏綏，登山崔嵬。昭告顯功，大福允興。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>詳《咸》之《賁》。</p><h3 id="損之大畜" tabindex="-1">損之大畜 <a class="header-anchor" href="#損之大畜" aria-label="Permalink to “損之大畜”">​</a></h3><h3 id="林辞-25" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-25" aria-label="Permalink to “林辞”">​</a></h3><p>嬰兒孩子，未有知誠。彼童而角，亂我政事。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>艮為嬰兒，震為孩子，艮為角，伏坤為亂、為政事，《毛詩傳》&quot;童，羊之無角&quot;者也。○子，汲古作笑，非，依宋元本。彼，元本訛狄，依汲古。角，宋元、汲古作爭，依《巽》之《節》校。《大雅》&quot;彼重而角實虹&quot;。小子、孩子，本微子及《易明夷六五》。</p><h3 id="損之頤" tabindex="-1">損之頤 <a class="header-anchor" href="#損之頤" aria-label="Permalink to “損之頤”">​</a></h3><h3 id="林辞-26" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-26" aria-label="Permalink to “林辞”">​</a></h3><p>十丸同投，為雉所離。獨得逃脫，完全不虧。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>坤數十，坎為丸，伏大坎故曰十丸。坤為雉，離罹同，遭也。震為逃脫。○離，宋元本、汲古作維，依局本。逃，宋元本作跳，跳逃通。《史記》漢王跳是其證。不，汲古作所，依宋元本。</p><h3 id="損之大過" tabindex="-1">損之大過 <a class="header-anchor" href="#損之大過" aria-label="Permalink to “損之大過”">​</a></h3><h3 id="林辞-27" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-27" aria-label="Permalink to “林辞”">​</a></h3><p>狐濟濡尾，求橘得枳。季薑懷悔，鮑舍魚臰。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>伏艮為狐、為尾、為求、為橘、為枳，巽為薑，上兌故曰季薑。巽為鮑魚、為臭，伏坤為悔、為淮，上艮為橘，下震為反艮，而中隔坤水，《考工記》&quot;橘逾淮為枳&quot;。以反艮為枳，其切當神妙，真不可思議矣。臰臭同，汲古作斃，非。○求橘，汲古作來揭，依宋元本。</p><h3 id="損之坎" tabindex="-1">損之坎 <a class="header-anchor" href="#損之坎" aria-label="Permalink to “損之坎”">​</a></h3><h3 id="林辞-28" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-28" aria-label="Permalink to “林辞”">​</a></h3><p>踆足息肩，所忌不難。金城銅郭，以鐵為關。藩屏周衛，安全無患。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>震為足，艮為踆，止也。艮為金銅、為鐵、為城郭、為關、為藩屏，震為周、為衛，艮為安。○踆，宋元本作跌，依汲古。</p><h3 id="損之離" tabindex="-1">損之離 <a class="header-anchor" href="#損之離" aria-label="Permalink to “損之離”">​</a></h3><h3 id="林辞-29" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-29" aria-label="Permalink to “林辞”">​</a></h3><p>戴堯扶禹，松喬彭祖。西過王母，道路夷易，無敢難者。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>詳《訟》之《家人》。○路，元刊作里，依宋本、汲古。</p><h3 id="損之咸" tabindex="-1">損之咸 <a class="header-anchor" href="#損之咸" aria-label="Permalink to “損之咸”">​</a></h3><h3 id="林辞-30" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-30" aria-label="Permalink to “林辞”">​</a></h3><p>京庾積聚，黍稷以極。行者疾至，可以厭飽。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>《爾雅》：&quot;丘絕高曰京&quot;。《詩小雅》：&quot;會孫之庾，如坻如京&quot;，《傳》：&quot;京，高丘也&quot;。艮為京庾，互大坎，故曰積聚。巽為黍稷，伏震為行，中實故曰厭飽，厭饜同，足也。</p><h3 id="損之恒" tabindex="-1">損之恒 <a class="header-anchor" href="#損之恒" aria-label="Permalink to “損之恒”">​</a></h3><h3 id="林辞-31" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-31" aria-label="Permalink to “林辞”">​</a></h3><p>良夫孔姬，脅悝登臺。柴季不扶，衛輒走逃。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>《左傳哀十五年》：渾良夫與太子蒯蕢脅孔悝使立之。柴，高柴。季，子路。不扶者，言不扶衛輒也。震為夫、為姬、為孔，伏艮為台、為季，艮手為扶，艮伏故不扶。震為衛，為逃。○夫，宋本訛天，依元本、汲古。孔，汲古作●，脅悝作負理，均依宋元木。柴，宋元本作樂，或又作欒，謂為欒寧，亦孔氏家臣，汲古又作昆，均非，依局本。孔姬，孔悝母。</p><h3 id="損之遯" tabindex="-1">損之遯 <a class="header-anchor" href="#損之遯" aria-label="Permalink to “損之遯”">​</a></h3><h3 id="林辞-32" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-32" aria-label="Permalink to “林辞”">​</a></h3><p>天之所與，福祿常在，不憂危殆。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>乾為福祿。</p><h3 id="損之大壯" tabindex="-1">損之大壯 <a class="header-anchor" href="#損之大壯" aria-label="Permalink to “損之大壯”">​</a></h3><h3 id="林辞-33" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-33" aria-label="Permalink to “林辞”">​</a></h3><p>行觸天剛，馬死車傷。身無寥賴，困窮乏糧。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>《參同契》天罡據西，註：天罡即北斗，《家人》之《漸》曰魁罡，所當初為敗殃，故曰馬死車傷。伏艮為星，故曰天罡。震為馬、為車，伏坤為身、為窮乏，震為糧。○剛，汲古作綱，依宋元本。剛罡同。寥，宋元本作憀，依汲古。</p><h3 id="損之晉" tabindex="-1">損之晉 <a class="header-anchor" href="#損之晉" aria-label="Permalink to “損之晉”">​</a></h3><h3 id="林辞-34" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-34" aria-label="Permalink to “林辞”">​</a></h3><p>鉛刀切玉，堅不可得。盡我筋力，胝蠒為疾。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>艮為刀，坤柔故曰鉛刀，艮為堅，多節，故曰胝蠒。坎為疾，玉或為艮堅象。○蠒，汲古作胼，依宋元本。蠒，繭俗字，胝蠒，言皮肉皴裂也。</p><h3 id="損之明夷" tabindex="-1">損之明夷 <a class="header-anchor" href="#損之明夷" aria-label="Permalink to “損之明夷”">​</a></h3><h3 id="林辞-35" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-35" aria-label="Permalink to “林辞”">​</a></h3><p>穆違百裡，使孟奮武。將軍帥戰，敗於淆口。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>詳《蹇》之《離》。坤為百裡，震為孟、為武、為口。○違，汲古作逢，帥作師，均依宋元本。</p><h3 id="損之家人" tabindex="-1">損之家人 <a class="header-anchor" href="#損之家人" aria-label="Permalink to “損之家人”">​</a></h3><h3 id="林辞-36" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-36" aria-label="Permalink to “林辞”">​</a></h3><p>有人追亡，鳥言所匿，不日而得。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>通《解》。震為亡、為追、為人、為言，離為鳥，坎隱，故曰匿。離為日。此必有故事。如公冶長解鳥言之類，而今不能考。○鳥，汲古作為，依宋元本。日而，宋元本作旅日，依汲古。</p><h3 id="損之睽" tabindex="-1">損之睽 <a class="header-anchor" href="#損之睽" aria-label="Permalink to “損之睽”">​</a></h3><h3 id="林辞-37" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-37" aria-label="Permalink to “林辞”">​</a></h3><p>府藏之富，王以振貸。捕魚河海，罟網多得。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>此全用遇卦《損》象。坤為府藏、為多，故曰富。震為王、為振。振賑同，而古皆作振。坤為魚、為河海，離為網罟，互大離，故曰多得。○罟，宋元作苟，笱之訛字，依汲古。</p><h3 id="損之蹇" tabindex="-1">損之蹇 <a class="header-anchor" href="#損之蹇" aria-label="Permalink to “損之蹇”">​</a></h3><h3 id="林辞-38" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-38" aria-label="Permalink to “林辞”">​</a></h3><p>鴻飛遵陸，公歸不復，伯氏客宿。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>艮為鴻、為陸，震為公、為歸，震覆故不復。《豳風詩九罭篇》：&quot;鴻飛遵陸，公歸不復&quot;，公謂周公。</p><h3 id="損之解" tabindex="-1">損之解 <a class="header-anchor" href="#損之解" aria-label="Permalink to “損之解”">​</a></h3><h3 id="林辞-39" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-39" aria-label="Permalink to “林辞”">​</a></h3><p>鳧過稻廬，甘樂鱑暋Ｋ渚不去，田畯懷憂。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>此仍用遇卦《損》象。震為鳧、為稻、為樂，艮為廬，坤為魚，故曰鱑暋Ｕ鷂驚，艮止故不去。坤為田，畯，農官也，艮為官，坤為憂。○鱑暎汲古作曲，依宋元本。</p><h3 id="損之損" tabindex="-1">損之損 <a class="header-anchor" href="#損之損" aria-label="Permalink to “損之損”">​</a></h3><h3 id="林辞-40" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-40" aria-label="Permalink to “林辞”">​</a></h3><p>路多枳棘，步刺我足。不利旅客，為心所毒。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>詳《履》之《遯》。</p><h3 id="損之益" tabindex="-1">損之益 <a class="header-anchor" href="#損之益" aria-label="Permalink to “損之益”">​</a></h3><h3 id="林辞-41" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-41" aria-label="Permalink to “林辞”">​</a></h3><p>雨師娶婦，黃嚴季女。成禮既婚，相呼南去。膏澤田裡，年豐大喜。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>詳《恆》之《晉》。南去，宋元本作面南，汲古作而南，依《師》之《恆》校。澤，元本作潤，依宋本、汲古。田裡，依《恆》之《晉》校，各本作應時。</p><h3 id="損之夬" tabindex="-1">損之夬 <a class="header-anchor" href="#損之夬" aria-label="Permalink to “損之夬”">​</a></h3><h3 id="林辞-42" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-42" aria-label="Permalink to “林辞”">​</a></h3><p>積蓄有餘，糞土不居。美哉輪奐，出有高車。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>乾實故曰積，坤為糞土，坤伏故曰不居。伏大艮為宮室，故曰輪奐、曰高。坤為大輿。○糞，宋元訛冀，依汲古。《禮檀弓下》：&quot;美哉輪焉，美哉奐焉&quot;，言高大也。</p><h3 id="損之姤" tabindex="-1">損之姤 <a class="header-anchor" href="#損之姤" aria-label="Permalink to “損之姤”">​</a></h3><h3 id="林辞-43" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-43" aria-label="Permalink to “林辞”">​</a></h3><p>重門擊柝，介士守護。終有他道，雖驚不懼。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>此仍用遇卦《損》象。損二至上正反兩艮相對，故曰重門。震為柝，艮為擊、為介，介，甲也，為守護、為終、為道路，震為驚，坤為懼。</p><h3 id="損之萃" tabindex="-1">損之萃 <a class="header-anchor" href="#損之萃" aria-label="Permalink to “損之萃”">​</a></h3><h3 id="林辞-44" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-44" aria-label="Permalink to “林辞”">​</a></h3><p>大都王市，稠人多寶。公孫宜賈，資貨萬倍。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>坤為大都，巽為市，伏震為人、為寶，坤為多，故曰稠人多寶。震為公，艮為孫，巽為賈，故曰公孫宜賈。坤為資貨、為萬，巽為倍，故曰萬倍。○資貨，宋元作其貸，依汲古。</p><h3 id="損之升" tabindex="-1">損之升 <a class="header-anchor" href="#損之升" aria-label="Permalink to “損之升”">​</a></h3><h3 id="林辞-45" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-45" aria-label="Permalink to “林辞”">​</a></h3><p>秋隼冬翔，數被嚴霜。甲兵充庭，萬物不生。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>詳《賁》之《隨》。宋元本多&quot;雄父夜鳴，民擾以驚&quot;八字，依汲古。</p><h3 id="損之困" tabindex="-1">損之困 <a class="header-anchor" href="#損之困" aria-label="Permalink to “損之困”">​</a></h3><h3 id="林辞-46" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-46" aria-label="Permalink to “林辞”">​</a></h3><p>招禍致凶，來螫我邦。痛在手足，不得安息。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>通《賁》。坎為禍、為痛、為螫，艮為邦、為手，震為足，正反震故不得息。</p><h3 id="損之井" tabindex="-1">損之井 <a class="header-anchor" href="#損之井" aria-label="Permalink to “損之井”">​</a></h3><h3 id="林辞-47" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-47" aria-label="Permalink to “林辞”">​</a></h3><p>秦失其鹿，疾走先得。勇夫慕義，君子率服。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>兌西，故曰秦。伏震為鹿，坎為●、為疾，震為走、為勇夫，艮為君子。○疾走，汲古作高足，依宋元本。率，宋元本作變，依汲古。</p><h3 id="損之革" tabindex="-1">損之革 <a class="header-anchor" href="#損之革" aria-label="Permalink to “損之革”">​</a></h3><h3 id="林辞-48" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-48" aria-label="Permalink to “林辞”">​</a></h3><p>山陵四塞，遏我徑路。欲還不得，復我故處。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>已詳《同人》之《革》。</p><h3 id="損之鼎" tabindex="-1">損之鼎 <a class="header-anchor" href="#損之鼎" aria-label="Permalink to “損之鼎”">​</a></h3><h3 id="林辞-49" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-49" aria-label="Permalink to “林辞”">​</a></h3><p>一指食肉，口無所得，舌饞於腹。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>詳《頤》之《離》。一當作以，饞，宋元本作讒。</p><h3 id="損之震" tabindex="-1">損之震 <a class="header-anchor" href="#損之震" aria-label="Permalink to “損之震”">​</a></h3><h3 id="林辞-50" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-50" aria-label="Permalink to “林辞”">​</a></h3><p>晨夜驚駭，不知所止。皇母相佑，卒得安處。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>震為晨，互坎為夜，艮為止，坎隱，故不知。伏巽為母，震為王，故曰王母。互艮為安。</p><h3 id="損之艮" tabindex="-1">損之艮 <a class="header-anchor" href="#損之艮" aria-label="Permalink to “損之艮”">​</a></h3><h3 id="林辞-51" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-51" aria-label="Permalink to “林辞”">​</a></h3><p>豺狼所言，語無成全。誤我白馬，使乾口來。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>艮為豹狼，互震為言語，正反震，故曰誤。震為馬、為白、為口，互大離，故曰乾口。○誤，汲古作設，非，依宋元本。</p><h3 id="損之漸" tabindex="-1">損之漸 <a class="header-anchor" href="#損之漸" aria-label="Permalink to “損之漸”">​</a></h3><h3 id="林辞-52" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-52" aria-label="Permalink to “林辞”">​</a></h3><p>呼精靈來，魄生無憂。疾病瘳愈，解我患愁。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>通《歸妹》。震為呼、為帝，故曰精靈。兌為月，震生震樂，而納庚，初三月出庚，故曰魄生無憂。坎為疾病、為憂，震解，故病愈而不愁也。○愈，宋元本作愈，依汲古。</p><h3 id="損之歸妹" tabindex="-1">損之歸妹 <a class="header-anchor" href="#損之歸妹" aria-label="Permalink to “損之歸妹”">​</a></h3><h3 id="林辞-53" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-53" aria-label="Permalink to “林辞”">​</a></h3><p>牧羊逐兔，使魚捕鼠。任非其人，廢日無功，不免辛苦。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>兌羊震兔，伏巽為魚，坎為鼠，互離為日，坎勞故曰辛苦。羊逐兔，魚捕鼠，皆失使，猶任人不當而無功也。○捕鼠，宋元本作相捕，非，依汲古。廢日，汲古作卒歲，依宋元本。</p><h3 id="損之豐" tabindex="-1">損之豐 <a class="header-anchor" href="#損之豐" aria-label="Permalink to “損之豐”">​</a></h3><h3 id="林辞-54" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-54" aria-label="Permalink to “林辞”">​</a></h3><p>堂祥上樓，與福俱居。帝姬冶好，國安無憂。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>堂祥，疑與徜徉同。伏艮為堂、為樓、為居、為國、為安，震為帝、為姬，兌為冶好，互坎為憂，震解故無。○第三句宋元本作席地妃治，依汲古。</p><h3 id="損之旅" tabindex="-1">損之旅 <a class="header-anchor" href="#損之旅" aria-label="Permalink to “損之旅”">​</a></h3><h3 id="林辞-55" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-55" aria-label="Permalink to “林辞”">​</a></h3><p>禹召諸神，會稽南山。執玉萬國，天下康安。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>通《節》。震為王，坎勞故曰禹。震為神，坎眾，故曰諸神。艮為山，震南，故曰會稽南山。震為玉，艮為執、為國，坎眾，故曰萬國。艮為天、為安。○神，宋元本作臣，非，依汲古。張衡賦&quot;嘉群神之執玉兮，疾防風之食言&quot;，是自漢皆作群神，神，猶後也。</p><h3 id="損之巽" tabindex="-1">損之巽 <a class="header-anchor" href="#損之巽" aria-label="Permalink to “損之巽”">​</a></h3><h3 id="林辞-56" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-56" aria-label="Permalink to “林辞”">​</a></h3><p>太姒文母，仍生聖子。昌發受命，為天下主。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>太姒，文王妃，生武王發，文母為太任，《詩》&quot;思齊大任，文王之母&quot;是也。大任生昌，太姒生髮，故曰仍生。《大雅》&quot;大任有身，生此文王&quot;，又曰&quot;纘女維莘，長子維行，篤生武王&quot;，林所本也。巽為母，互離，故曰文母。伏震為子，坎為聖，巽為命，伏震為主，伏艮為天，故曰為天下主。</p><h3 id="損之兌" tabindex="-1">損之兌 <a class="header-anchor" href="#損之兌" aria-label="Permalink to “損之兌”">​</a></h3><h3 id="林辞-57" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-57" aria-label="Permalink to “林辞”">​</a></h3><p>兩罝同室，兔無誰告。與狂相觸，蒙我以惡。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>互離為罝，兌卦數二，故曰兩罝。伏坎為室，震為兔，震伏，故兔無。伏震為狂，三至上正反震相對，故曰與狂相觸。《說文》：&quot;室，實也&quot;，言罝原有兔，因觸兔逸反疑我也。</p><h3 id="損之渙" tabindex="-1">損之渙 <a class="header-anchor" href="#損之渙" aria-label="Permalink to “損之渙”">​</a></h3><h3 id="林辞-58" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-58" aria-label="Permalink to “林辞”">​</a></h3><p>桃雀竊脂，巢於小枝。動搖不安，為風所吹。心寒悚惕，常憂殆危。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>已詳《噬嗑》之《渙》。</p><h3 id="損之節" tabindex="-1">損之節 <a class="header-anchor" href="#損之節" aria-label="Permalink to “損之節”">​</a></h3><h3 id="林辞-59" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-59" aria-label="Permalink to “林辞”">​</a></h3><p>陽春長日，萬物華實，樂有利福。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>震為春、為長，互大離故曰長日。震為萬物、為華，艮為果蓏，故曰實。震為樂、為福，伏巽為利。</p><h3 id="損之中孚" tabindex="-1">損之中孚 <a class="header-anchor" href="#損之中孚" aria-label="Permalink to “損之中孚”">​</a></h3><h3 id="林辞-60" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-60" aria-label="Permalink to “林辞”">​</a></h3><p>鄰不我顧，而望玉女。身疾瘡癩，誰肯媚者。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>震為鄰，艮為顧，二四艮反，故不我顧。艮為我、為望，震為玉，兌為女、為媚，故曰玉女。艮為身而多節，故曰瘡癩。○我顧，汲古作顧我，依宋元本，言不反省。</p><h3 id="損之小過" tabindex="-1">損之小過 <a class="header-anchor" href="#損之小過" aria-label="Permalink to “損之小過”">​</a></h3><h3 id="林辞-61" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-61" aria-label="Permalink to “林辞”">​</a></h3><p>涸旱不雨，澤竭無流。魚鱉乾口，皇天不憂。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>艮為火，故曰涸旱。兌為雨澤，艮止，故不流。巽為魚，艮為鱉，兌為口，艮火在下，故曰乾口。震為帝、為皇，艮為天，震樂，故不憂。言災重如此而天不恤。</p><h3 id="損之既濟" tabindex="-1">損之既濟 <a class="header-anchor" href="#損之既濟" aria-label="Permalink to “損之既濟”">​</a></h3><h3 id="林辞-62" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-62" aria-label="Permalink to “林辞”">​</a></h3><p>狼虎之鄉，日爭凶訟。受性貪饕，不能容縱。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>半象，重艮故曰狼虎、曰鄉。坎上下口相背，故訟。離為日，又取損象，於爭訟尤切。</p><h3 id="損之未濟" tabindex="-1">損之未濟 <a class="header-anchor" href="#損之未濟" aria-label="Permalink to “損之未濟”">​</a></h3><h3 id="林辞-63" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-63" aria-label="Permalink to “林辞”">​</a></h3><p>陰註陽疾，水離其室。舟楫大作，傷害黍稷。民飢於食，亦病心腹。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>三陰皆在內，故曰註。註，灌也。陽皆在外，故疾，《雜卦》未濟男之窮也，與此旨同。離罹同。坎為水、為室，半震為舟，坎為楫，重震重坎，故曰大作。震為黍稷，坎為病、為心，離為腹。</p>',322)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
